  right: 20px !important;
  bottom: 25px !important;
  margin: 10px;
  z-index: 9999;
}
.yobiToasts .toast {
  position: relative;
  width: 450px;
  word-break: keep-all;
  word-wrap: break-word;
  margin: 10px;
  padding: 10px 20px;
  outline: none;
  font-weight: bold;
  box-sizing: border-box;
  color: black;
  background-color: #cddc39;
  -webkit-transition-duration: 0.3s;
  box-shadow: 1px 1px 3px black;
  opacity: 0.9;
  -webkit-border-radius: 2px;
  -moz-border-radius: 2px;
  border-radius: 2px;
}
.yobiToasts .toast .btn-dismiss {
  position: absolute;
  top: 5px;
  left: 420px;
}
.yobiToasts .toast .btn-dismiss button {
  color: black;
  font-size: 25px;
  font-weight: bold;
}
.yobiToasts .toast .v {
  display: inline-block;
  width: 0;
  height: 50px;
  vertical-align: middle;
}
.yobiToasts .toast .msg {
  width: 90%;
  font-size: 15px;
  display: inline-block;
  word-wrap: break-word;
  word-break: break-all;
  margin: 0;
  vertical-align: middle;
}
.yobiSpinner {
  display: none;
  position: fixed;
  z-index: 99999;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
}
.yobiSpinner .spinContainer {
  position: fixed;
  width: 100px;
  height: 100px;
  top: 50%;
  left: 50%;
}
