[data-owner="left-sidebar-project-shell"] > div:nth-child(3) > ul::-webkit-scrollbar,
[data-owner="left-sidebar-project-shell"] > div:nth-child(3) > div::-webkit-scrollbar {
  background-color: #d3d3d3;
  height: 10px;
  width: 5px;
}
[data-owner="left-sidebar-project-shell"] > div:nth-child(3) > ul::-webkit-scrollbar-thumb,
[data-owner="left-sidebar-project-shell"] > div:nth-child(3) > div::-webkit-scrollbar-thumb {
  background-color: #2788ba;
}
[data-owner="left-sidebar-project-shell"] > div:nth-child(3) > [data-active="true"] {
  display: block;
}
[data-owner="left-sidebar-project-shell"] > div:nth-child(3) > div[data-active="true"] {
  color: mediumvioletred;
  font-size: 16px;
  margin: 10px 0 25px;
  text-align: center;
}

/* project subtabs */
[data-owner="left-sidebar-project-subtabs"] {
  padding: 10px 0 5px;
}
[data-owner="left-sidebar-project-subtabs"] > ul {
  background-color: #eeeeee;
  color: #000000;
  display: inline-block;
  list-style-type: none;
  margin: 0;
  padding: 0;
}
[data-owner="left-sidebar-project-subtabs"] > ul > li {
  border-style: none;
  border-width: 0;
  display: inline-block;
  margin-left: 0;
}
[data-owner="left-sidebar-project-subtabs"] > ul > li > button {
  appearance: none;
  background-color: transparent;
  border-radius: 0;
  border-style: none;
  border-width: 0;
  box-shadow: none;
  color: inherit;
  cursor: pointer;
  display: block;
  font: inherit;
  line-height: 20px;
  margin: 0;
  padding: 5px 8px;
}
[data-owner="left-sidebar-project-subtabs"] > ul > li > button:hover,
[data-owner="left-sidebar-project-subtabs"] > ul > li > button:focus {
  background-color: transparent;
  border-bottom-color: #f36c22;
  border-bottom-style: solid;
  border-bottom-width: 1px;
  color: #000000;
  text-decoration: none;
}
[data-owner="left-sidebar-project-subtabs"] > ul > li > button[aria-pressed="true"],
[data-owner="left-sidebar-project-subtabs"] > ul > li > button[aria-pressed="true"]:hover,
[data-owner="left-sidebar-project-subtabs"] > ul > li > button[aria-pressed="true"]:focus {
  background-color: #f36c22;
  border-bottom-color: #f36c22;
  border-bottom-style: solid;
  border-bottom-width: 1px;
  color: #fcfcfc;
  text-decoration: none;
}

/* recent issue rows + popover */
[data-owner="left-sidebar-recent-issue-rows"] {
  cursor: pointer;
  line-height: normal;
}
[data-owner="left-sidebar-recent-issue-rows"] > div {
  align-items: center;
  background-color: transparent;
  cursor: pointer;
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  justify-content: space-between;
  padding: 4px 0;
  position: relative;
}
[data-owner="left-sidebar-recent-issue-rows"] > div:hover {
  background-color: rgba(255, 255, 255, 0.15);
}
[data-owner="left-sidebar-recent-issue-rows"] > div > a {
  align-items: center;
  background-color: transparent;
  color: #ffffff;
  display: flex;
  flex-direction: row;
  flex-grow: 1;
  flex-wrap: nowrap;
  font-size: 14px;
  font-weight: 400;
  justify-content: space-between;
  overflow: hidden;
  text-decoration: none;
}
[data-owner="left-sidebar-recent-issue-rows"] > div > a:hover,
[data-owner="left-sidebar-recent-issue-rows"] > div > a:focus {
  color: #ffffff;
  text-decoration: none;
}
[data-owner="left-sidebar-recent-issue-rows"] .issue-item {
  align-items: center;
  display: block;
  flex-direction: row;
  flex-grow: 1;
  flex-wrap: nowrap;
  justify-content: space-between;
  overflow: hidden;
  padding-bottom: 1px;
  padding-left: 0;
  padding-right: 0;
  padding-top: 1px;
}
/* the frozen fallback pins .issue-item padding-left:5px !important; the left
   framed rows keep the legacy 0px gutter */
[data-owner="left-sidebar-recent-issue-rows"] .issue-item {
  padding-left: 0 !important;
}
[data-owner="left-sidebar-recent-issue-rows"] .issue-title-start,
[data-owner="left-sidebar-recent-issue-rows"] [data-owner="sidebar-recent-issue-marker"] {
  color: darkgray;
  display: inline-block;
  vertical-align: top;
  width: 10px;
}
[data-owner="left-sidebar-recent-issue-rows"] .issue-title,
[data-owner="left-sidebar-recent-issue-rows"] [data-owner="sidebar-recent-issue-title"] {
  color: #ffffff;
  display: inline-block;
  font-size: 13px;
  max-width: 240px;
  white-space: break-spaces;
  word-break: break-all;
}
[data-owner="left-sidebar-recent-issue-popover"] {
  background-clip: padding-box;
  background-color: #03a9f4;
  border-color: rgba(0, 0, 0, 0.2);
  border-radius: 2px;
  border-style: solid;
  border-width: 1px;
  box-shadow: -2px 2px 1px rgba(0, 0, 0, 0.1);
  color: #ffffff;
  display: block;
  font-size: 13px;
  left: 100%;
  line-height: 1;
  margin-left: 10px;
  max-width: 276px;
  min-width: 200px;
  overflow-wrap: break-word;
  padding: 1px;
  position: absolute;
  text-align: left;
  top: 50%;
  transform: translateY(-50%);
  white-space: normal;
  z-index: 1010;
}
[data-owner="left-sidebar-recent-issue-popover"] > div:first-child {
  /* F5 11px 11px 11px 0 — legacy bootstrap.css .popover .arrow (right-anchored
     popover left triangle); the shared rule above already pins this and this
     duplicate block must not regress it to a uniform border. */
  border-color: transparent;
  border-left-width: 0;
  border-right-color: rgba(0, 0, 0, 0.25);
  border-style: solid;
  border-width: 11px 11px 11px 0;
  display: block;
  height: 0;
  left: -11px;
  margin-top: -11px;
  position: absolute;
  top: 50%;
  width: 0;
}
[data-owner="left-sidebar-recent-issue-popover"] > div:first-child::after {
  border-color: transparent;
  border-left-width: 0;
  border-right-color: #03a9f4;
  border-style: solid;
  border-width: 10px 10px 10px 0;
  bottom: -10px;
  content: "";
  display: block;
  height: 0;
  left: 1px;
  position: absolute;
  width: 0;
}
[data-owner="left-sidebar-recent-issue-popover"] > div:last-child {
  line-height: 120%;
  padding: 9px 10px;
}

/* MarkdownCodeBlock (shared issue/post markdown code renderer): prism
   highlighting + floating copy button — modern improvement, not legacy
   parity (legacy Yona renders a plain <pre>). The copy button floats at the
   block's top-right and appears on hover. */
[data-owner="markdown-code-block"] pre {
  position: relative;
}
[data-owner="markdown-code-copy"] {
  position: absolute;
  top: 6px;
  right: 6px;
  z-index: 5;
  padding: 2px 8px;
  font-size: 11px;
  line-height: 16px;
  color: #555;
  background-color: rgba(255, 255, 255, 0.9);
  border: 1px solid #ddd;
  border-radius: 3px;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease;
}
[data-owner="markdown-code-block"]:hover [data-owner="markdown-code-copy"],
[data-owner="markdown-code-copy"]:focus-visible {
  opacity: 1;
}
[data-owner="markdown-code-copy"]:hover {
  background-color: #fff;
  color: #333;
  border-color: #ccc;
}
